import json,csv,collections,re
w=json.load(open('watchlist.json'))
cust={r['customer_id']:r for r in csv.DictReader(open('dev/customers_dev.csv'))}
labs=list(csv.DictReader(open('dev/labels_dev.csv')))
byclass=collections.defaultdict(list)
for l in labs: byclass[l['class']].append(l)
# crude: find wl entries sharing any 4-prefix token
def toks(n): return [t.strip('.,').lower() for t in re.split(r'[\s,-]+',n) if t.strip('.,')]
idx=collections.defaultdict(set)
for e in w:
    names=[e['primary_name']]+[a['name'] for a in e['aliases']]
    for n in names:
        for t in toks(n):
            if len(t)>=4: idx[t[:4]].add(e['uid'])
byuid={e['uid']:e for e in w}
for cls in ['D2_near_name','D6_same_given','D1_name_dob_conflict']:
    print('#####',cls)
    for l in byclass[cls][:12]:
        c=cust[l['customer_id']]
        print(' CUST:',repr(c['full_name']),c['dob'])
        cands=collections.Counter()
        for t in toks(c['full_name']):
            if len(t)>=4:
                for u in idx[t[:4]]: cands[u]+=1
        for u,n in cands.most_common(3):
            e=byuid[u]
            print('    ',n,u,repr(e['primary_name']),e['dob'],[a['name'] for a in e['aliases']])
