#!/usr/bin/env python3
"""Score decisions against dev labels, overall and per class."""
import csv, sys, collections

def load(p, key):
    with open(p, newline='', encoding='utf-8') as f:
        return {r[key]: r for r in csv.DictReader(f)}

def main():
    dec = load(sys.argv[1], 'customer_id')
    lab = load(sys.argv[2], 'customer_id')
    cust = load(sys.argv[3], 'customer_id') if len(sys.argv) > 3 else {}
    verbose = '-v' in sys.argv

    tp = fp = fn = 0
    uid_ok = 0
    byclass = collections.defaultdict(lambda: [0, 0])  # [n, bad]
    errors = collections.defaultdict(list)
    for cid, l in lab.items():
        exp = l['expected_decision']
        cls = l['class']
        d = dec.get(cid)
        got = d['decision'] if d else 'NO_MATCH'
        gotu = (d.get('matched_uid') or '') if d else ''
        byclass[cls][0] += 1
        ok = True
        if exp == 'MATCH':
            if got == 'MATCH':
                tp += 1
                if gotu == l['expected_uid']:
                    uid_ok += 1
                else:
                    ok = False
                    errors[cls].append((cid, 'WRONGUID', l['expected_uid'], gotu))
            else:
                fn += 1; ok = False
                errors[cls].append((cid, 'FN', l['expected_uid'], ''))
        else:
            if got == 'MATCH':
                fp += 1; ok = False
                errors[cls].append((cid, 'FP', '', gotu))
        if not ok:
            byclass[cls][1] += 1

    rec = tp / (tp + fn) if tp + fn else 1.0
    prec = tp / (tp + fp) if tp + fp else 1.0
    print(f'TP={tp} FP={fp} FN={fn}  recall={rec:.4f} precision={prec:.4f} uid_ok={uid_ok}/{tp}')
    print(f'{"class":28s} {"n":>5s} {"bad":>5s}  rate')
    for cls in sorted(byclass):
        n, bad = byclass[cls]
        flag = ''
        if cls.startswith('T') and n and (n - bad) / n < 0.90: flag = '  <== RECALL FAIL'
        if cls.startswith('D') and n and bad / n > 0.05: flag = '  <== FP FAIL'
        if cls.startswith('R') and n and bad / n > 0.01: flag = '  <== FP FAIL'
        print(f'{cls:28s} {n:5d} {bad:5d}  {bad/n if n else 0:.3f}{flag}')
    if verbose:
        for cls in sorted(errors):
            print('---', cls)
            for cid, kind, exp, got in errors[cls][:200]:
                nm = cust.get(cid, {})
                print(f'  {cid} {kind} exp={exp} got={got}  {nm.get("full_name","")!r} dob={nm.get("dob","")} id={nm.get("id_type","")}:{nm.get("id_number","")} type={nm.get("type","")}')

main()

